fields.InputDefinition:
{
  "goal": "In Component Studio → Form Studio, open an existing form in the left rail. Below the forms list, verify the 'Versions' panel renders showing version rows (v1, v2, …) with Active/Pending/Inactive tags — or a 'No version history yet' empty state if the form has none. If two or more versions exist, click the diff (code-compare) icon on one version row, then on another, to open the 'Compare versions' dialog showing side-by-side A/B code panes. Pages can take 10-30s to load — wait, don't navigate away. Seeing the versions panel render (and, when 2+ versions exist, the diff dialog open) is success. A clean 'no version history' empty state is also a pass.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Opening a form shows a 'Versions' panel with version rows (with Active/Pending/Inactive tags) or a clear 'No version history yet' empty state",
    "When multiple versions exist, initiating a diff opens a 'Compare versions' dialog with two side-by-side code panes",
    "No error messages, blank screens, or crash pages"
  ]
}
